function m42GeometryCanonicalPrevious(raw,file){
 const selected=m42GeometryCanonicalSourceHistory.find(row=>row.path===file);if(!selected)return raw;
 const identity=body=>({path:file,bytes:body.length,sha256:createHash('sha256').update(body).digest('hex')});
 if(JSON.stringify(identity(raw))!==JSON.stringify(selected.current))return raw;
 let text=raw.toString('utf8');
 for(const inverse of selected.inverse){
  assert.equal(text.split(inverse.from).length,2,'Exact canonical geometry inverse differs');
  text=text.replace(inverse.from,()=>inverse.to);
 }
 const previous=Buffer.from(text);assert.deepEqual(identity(previous),selected.predecessor);return previous;
}

