 if(JSON.stringify(current)===JSON.stringify(keyboardPackage.current)){const value=JSON.parse(raw.toString());delete value.exports['./web/keyboard'];delete value.imports['#egret-keyboard-input'];raw=Buffer.from(JSON.stringify(value,null,2)+'\n');assert.deepEqual({path:file,bytes:raw.length,sha256:createHash('sha256').update(raw).digest('hex')},keyboardPackage.base);current=keyboardPackage.base;}
